#include "s61_binary_deeper_cubic_field_20261101.hpp"
#include <chrono>
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
int main(int argc,char**argv){assert(argc==4);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),kin(argv[2]);ofstream out(argv[3]);assert(in&&kin&&out);int nr,nc,nk=75;in>>nr>>nc;assert(nr==117&&nc==106);vector<vector<Poly>>A(nr,vector<Poly>(nc)),K(nc,vector<Poly>(nk));for(auto&r:A)for(auto&p:r)read_poly(in,p.p);for(int j=0;j<nk;j++){string s;int n;kin>>s>>n;assert(s=="KERNEL"&&n==j);Poly den;read_poly(kin,den.p);for(int i=0;i<nc;i++)read_poly(kin,K[i][j].p);}out<<nr<<' '<<nk<<'\n';auto start=chrono::steady_clock::now();long total=0;for(int i=0;i<nr;i++){vector<Poly>row(nk);Poly tmp,g,h,q;for(int j=0;j<nk;j++)for(int k=0;k<nc;k++)if(!fmpq_mpoly_is_zero(A[i][k].p,ctx)&&!fmpq_mpoly_is_zero(K[k][j].p,ctx)){fmpq_mpoly_mul(tmp.p,A[i][k].p,K[k][j].p,ctx);fmpq_mpoly_add(row[j].p,row[j].p,tmp.p,ctx);}for(auto&v:row){assert(fmpq_mpoly_gcd(h.p,g.p,v.p,ctx));g=h;}write(out,g);long terms=0;if(!fmpq_mpoly_is_zero(g.p,ctx)){for(auto&v:row){assert(fmpq_mpoly_divides(q.p,v.p,g.p,ctx));v=q;terms+=fmpq_mpoly_length(v.p,ctx);}}for(auto&v:row)write(out,v);total+=terms;double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(i%10==0)cerr<<"PRODUCT "<<i<<" TERMS "<<terms<<" TOTAL "<<total<<" SEC "<<sec<<'\n';out.flush();assert(out.good());assert(total<4000000);}cerr<<"PASS TERMS "<<total<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
